function calculateVaR(returns, confidence = 0.95, method = "historical") {
  if (returns.length === 0) {
    throw new Error("No returns data provided");
  }
  if (method === "historical") {
    const sorted = [...returns].sort((a3, b2) => a3 - b2);
    const index = Math.floor((1 - confidence) * sorted.length);
    return sorted[Math.max(0, index)];
  } else {
    const mean = returns.reduce((a3, b2) => a3 + b2, 0) / returns.length;
    const std = Math.sqrt(
      returns.reduce((sum, r) => sum + Math.pow(r - mean, 2), 0) / returns.length
    );
    const zScore = normInv(1 - confidence);
    return mean - zScore * std;
  }
}
