import { config as config4 } from "dotenv";
import path10 from "path";
var envPaths = [
  ".env",
  path10.join(__dirname, "..", "..", "..", ".env"),
  // From adapter/../../../.env
  "/Users/louloulin/Documents/linchong/touzhi/dexter/.env"
];
for (const envPath of envPaths) {
  try {
    config4({ path: envPath, quiet: true });
    if (process.env.DEEPSEEK_API_KEY || process.env.ANTHROPIC_API_KEY) {
      break;
    }
  } catch {
  }
}
var prompt = process.argv.slice(2).join(" ");
if (!prompt) {
  console.error('Usage: bun run agent-bundle.js "your prompt here"');
  process.exit(1);
}
var model = process.env.DEFAULT_MODEL || "deepseek-v4-flash";
async function main() {
  const startTime = Date.now();
  console.log(JSON.stringify({
    type: "acpx.result",
    summary: "Agent started",
    stopReason: "started"
  }));
  try {
    const agent = await Agent.create({ model });
    const stream = agent.run(prompt);
    for await (const event of stream) {
      switch (event.type) {
        case "thinking":
          console.log(JSON.stringify({
            type: "acpx.text_delta",
            text: event.message,
            channel: "thought"
          }));
          break;
        case "tool_start":
          console.log(JSON.stringify({
            type: "acpx.tool_call",
            name: event.tool,
            toolCallId: event.toolCallId,
            status: "pending",
            text: JSON.stringify(event.args)
          }));
          break;
        case "tool_end":
          console.log(JSON.stringify({
            type: "acpx.tool_call",
            name: event.tool,
            toolCallId: event.toolCallId,
            status: "completed",
            text: event.result.slice(0, 500)
          }));
          break;
        case "tool_error":
          console.log(JSON.stringify({
            type: "acpx.error",
            message: event.error,
            code: "tool_error"
          }));
          break;
        case "done":
          const totalTime = Date.now() - startTime;
          console.log(JSON.stringify({
            type: "acpx.result",
            summary: event.answer.slice(0, 500),
            stopReason: `completed_after_${event.iterations}_iterations`,
            usage: event.tokenUsage,
            totalTimeMs: totalTime
          }));
          process.exit(0);
          break;
      }
    }
  } catch (error54) {
    const err = error54;
    console.log(JSON.stringify({
      type: "acpx.error",
      message: err.message,
      code: "agent_error"
    }));
    process.exit(1);
  }
}
main();
